class ExecutionBudgetManager:
    """Manages execution budgets for operations"""
    
    def __init__(self, limits: Optional[BudgetLimits] = None):
        self.limits = limits or BudgetLimits()
        self.usage = BudgetUsage()
        self.enabled = True
    
    def check_budget(self, tokens_required: int = 0, estimated_cost: float = 0.0, estimated_time: float = 0.0) -> bool:
        """Check if operation fits within remaining budget"""
        if not self.enabled:
            return True
        
        remaining_tokens = self.limits.max_tokens - self.usage.tokens_used
        remaining_cost = self.limits.max_cost - self.usage.cost_incurred
        remaining_time = self.limits.max_execution_time - self.usage.execution_time
        
        return (
            tokens_required <= remaining_tokens and
            estimated_cost <= remaining_cost and
            estimated_time <= remaining_time
        )
    
    def consume_budget(self, tokens: int = 0, cost: float = 0.0, time: float = 0.0) -> bool:
        """Consume budget for operation"""
        if not self.check_budget(tokens, cost, time):
            return False
        
        self.usage.tokens_used += tokens
        self.usage.cost_incurred += cost
        self.usage.execution_time += time
        return True
    
    def get_remaining_budget(self) -> Dict[str, float]:
        """Get remaining budget amounts"""
        return {
            "tokens": self.limits.max_tokens - self.usage.tokens_used,
            "cost": self.limits.max_cost - self.usage.cost_incurred,
            "time": self.limits.max_execution_time - self.usage.execution_time
        }
    
    @property
    def current_usage(self) -> Dict[str, Any]:
        """Get current usage information"""
        return {
            "tokens_remaining": self.limits.max_tokens - self.usage.tokens_used,
            "requests_remaining": 1000,  # Mock value for tests
            "budget_exceeded": {
                "tokens": self.usage.tokens_used >= self.limits.max_tokens,
                "cost": self.usage.cost_incurred >= self.limits.max_cost,
                "time": self.usage.execution_time >= self.limits.max_execution_time
            }
        }
    
    def reset_budget(self) -> None:
        """Reset budget usage"""
        self.usage.reset()
    
    def reset_usage(self) -> None:
        """Reset usage tracking (alias for reset_budget)"""
        self.usage.reset()
    
    def configure(self, limits=None, **kwargs) -> None:
        """Configure budget manager with parameters"""
        if limits:
            for key, value in limits.__dict__.items():
                if hasattr(self.limits, key):
                    setattr(self.limits, key, value)
        for key, value in kwargs.items():
            if hasattr(self.limits, key):
                setattr(self.limits, key, value)
    
    def enable(self) -> None:
        """Enable budget enforcement"""
        self.enabled = True
    
    def disable(self) -> None:
        """Disable budget enforcement"""
        self.enabled = False
    
    def record_tokens(self, operation: str, tokens: int) -> None:
        """Record token usage for a specific operation"""
        self.usage.tokens_used += tokens
    
    def record_request(self, operation: str) -> None:
        """Record a request for a specific operation"""
        # For now, just track that a request was made
        pass
    
    def increment_depth(self) -> None:
        """Increment execution depth"""
        if not hasattr(self.usage, 'current_depth'):
            self.usage.current_depth = 0
        self.usage.current_depth += 1
    
    def decrement_depth(self) -> None:
        """Decrement execution depth"""
        if hasattr(self.usage, 'current_depth') and self.usage.current_depth > 0:
            self.usage.current_depth -= 1
    
    def check_context_size(self, context_size: int) -> bool:
        """Check if context size is within limits"""
        return context_size <= 128000  # Default context limit
    
    def check_message_length(self, message_length: int) -> bool:
        """Check if message length is within limits"""
        return message_length <= 4000  # Default message limit


_global_budget_manager: Optional[ExecutionBudgetManager] = None


